package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestAFactIsAConstantForEachOfItsValues(t *testing.T) {
	got, err := render("a-fact", []byte(`{"_comment": ["not a value"], "some_name": "a value", "limit": 100, "on": true}`))
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		"// Code generated by go generate from config/facts/a-fact.json. DO NOT EDIT.",
		"package facts",
		`AFactSomeName = "a value"`,
		"AFactLimit    = 100",
		"AFactOn       = true",
	} {
		if !strings.Contains(string(got), want) {
			t.Errorf("the generated file does not say %q:\n%s", want, got)
		}
	}
	if strings.Contains(string(got), "Comment") {
		t.Errorf("a comment was made a constant:\n%s", got)
	}
}

func TestAListOfObjectsIsATableInTheOrderGiven(t *testing.T) {
	got, err := render("a-fact", []byte(`{"kept": [{"name": "b", "first": true, "size": 2}, {"name": "a", "first": false, "size": 1.5}], "plain": "x"}`))
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		`APlain = "x"`,
		"type AFactKeptEntry struct {",
		"First bool",
		"Name  string",
		"Size  float64",
		"var AFactKept = []AFactKeptEntry{",
		`{First: true, Name: "b", Size: 2},`,
		`{First: false, Name: "a", Size: 1.5},`,
	} {
		if !strings.Contains(string(got), strings.Replace(want, "APlain", "AFactPlain", 1)) {
			t.Errorf("the generated file does not say %q:\n%s", want, got)
		}
	}
	if strings.Index(string(got), `Name: "b"`) > strings.Index(string(got), `Name: "a"`) {
		t.Errorf("the entries are not in the order the file gives them:\n%s", got)
	}
	only, err := render("a-fact", []byte(`{"kept": [{"n": 1}]}`))
	if err != nil || strings.Contains(string(only), "const (") || !strings.Contains(string(only), "N int") {
		t.Errorf("a fact that is only a table: %v\n%s", err, only)
	}
}

func TestAListOfValuesIsASliceOfTheirKind(t *testing.T) {
	got, err := render("a-fact", []byte(`{"servers": ["192.0.2.1", "192.0.2.2"], "ports": [1, 2]}`))
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{`var AFactServers = []string{"192.0.2.1", "192.0.2.2"}`, "var AFactPorts = []int{1, 2}"} {
		if !strings.Contains(string(got), want) {
			t.Errorf("the generated file does not say %q:\n%s", want, got)
		}
	}
	if _, err := render("a-fact", []byte(`{"mixed": ["a", 1]}`)); err == nil {
		t.Error("a list of two kinds was rendered")
	}
}

func TestATableWhoseEntriesDisagreeIsRefused(t *testing.T) {
	for name, raw := range map[string]string{
		"empty":            `{"t": []}`,
		"not objects":      `{"t": [{"a": 1}, "b"]}`,
		"a field missing":  `{"t": [{"a": 1, "b": 2}, {"a": 1, "c": 2}]}`,
		"a field too many": `{"t": [{"a": 1}, {"a": 1, "b": 2}]}`,
		"two kinds":        `{"t": [{"a": 1}, {"a": "one"}]}`,
		"a value inside":   `{"t": [{"a": [1]}]}`,
	} {
		if _, err := render("a-fact", []byte(raw)); err == nil {
			t.Errorf("%s was rendered", name)
		}
	}
}

func TestAFactThatCannotBeConstantsIsRefused(t *testing.T) {
	for name, raw := range map[string]string{
		"not an object":   `["a", "b"]`,
		"not JSON":        `{`,
		"only comments":   `{"_comment": []}`,
		"a list of lists": `{"names": [["a"]]}`,
		"an inner object": `{"inner": {"a": 1}}`,
	} {
		if _, err := render("a-fact", []byte(raw)); err == nil {
			t.Errorf("%s was rendered", name)
		}
	}
}

func TestEveryFactIsWrittenAndNoFileOutlivesItsFact(t *testing.T) {
	facts, out := t.TempDir(), t.TempDir()
	if err := os.WriteFile(filepath.Join(facts, "kept.json"), []byte(`{"a": "b"}`), 0o600); err != nil {
		t.Fatal(err)
	}
	stale := filepath.Join(out, "gone"+generated)
	other := filepath.Join(out, "facts.go")
	for _, f := range []string{stale, other} {
		if err := os.WriteFile(f, []byte("package facts\n"), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	if err := write(facts, out); err != nil {
		t.Fatal(err)
	}
	if _, err := os.Stat(filepath.Join(out, "kept"+generated)); err != nil {
		t.Errorf("the fact was not written: %v", err)
	}
	if _, err := os.Stat(stale); !os.IsNotExist(err) {
		t.Errorf("a file generated from a fact since removed is still there")
	}
	if _, err := os.Stat(other); err != nil {
		t.Errorf("a file the generator did not write was removed")
	}
}

func TestNothingToGenerateOrABadFactIsRefused(t *testing.T) {
	if err := write(t.TempDir(), t.TempDir()); err == nil {
		t.Error("a directory with no fact was accepted")
	}
	facts := t.TempDir()
	if err := os.WriteFile(filepath.Join(facts, "bad.json"), []byte(`{"a": [[1]]}`), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := write(facts, t.TempDir()); err == nil || !strings.Contains(err.Error(), "bad.json") {
		t.Errorf("a bad fact was not refused by its file: %v", err)
	}
}

func TestANameIsWrittenAsGoExportsIt(t *testing.T) {
	for in, want := range map[string]string{"untrusted-zone": "UntrustedZone", "not_yet_clean": "NotYetClean", "key": "Key"} {
		if got := identifier(in); got != want {
			t.Errorf("identifier(%q) = %q, want %q", in, got, want)
		}
	}
}
